export function assertNever(x, label){ throw new Error(`unexpected ${label}: ${String(x)}`); }
export function deepFreeze(o){ return o; }
export function isJsonValue(v){
  if (v === null) return true;
  const t = typeof v;
  if (t === 'string' || t === 'boolean') return true;
  if (t === 'number') return Number.isFinite(v) && !Object.is(v, -0);
  if (Array.isArray(v)) return v.every(isJsonValue);
  if (t === 'object') {
    if (Object.getPrototypeOf(v) !== Object.prototype && Object.getPrototypeOf(v) !== null) return false;
    return Object.values(v).every(isJsonValue);
  }
  return false;
}
export function snapshotJsonValue(v){ return v === undefined ? undefined : JSON.parse(JSON.stringify(v)); }
